"use client";

import React, { useState } from "react";
import { Star } from "lucide-react";

export function ReviewSummaryCard() {
  const [rating, setRating] = useState(4.8);

  return (
    <div className="w-full max-w-sm bg-card/45 backdrop-blur-xl border border-border/50 p-5 rounded-2xl shadow-xl select-none font-sans text-foreground">
      <div className="flex items-center justify-between mb-4">
        <div className="flex items-center gap-1.5">
          <Star className="w-4 h-4 text-yellow-400" />
          <span className="text-xs font-bold uppercase tracking-wider text-muted-foreground">Ratings Breakdown</span>
        </div>
        <span className="text-[9px] uppercase font-bold text-violet-400">952 total ratings</span>
      </div>

      <div className="space-y-4">
        <div>
          <div className="flex justify-between text-xs mb-1.5">
            <span className="text-muted-foreground/60">Groundedness (Hallucination Safe)</span>
            <span className="font-bold text-violet-400">{rating} / 5.0</span>
          </div>
          <div className="h-1.5 bg-secondary/40 rounded-full overflow-hidden">
            <div className="h-full bg-violet-500 rounded-full" style={{ width: `${(rating / 5) * 100}%` }} />
          </div>
        </div>
      </div>
    </div>
  );
}
